		{ id = "master-apothecary-faranell", name = "Mestre Boticário Faranell", note = "conhece a cabeça dele" },
		{ id = "sylvanas-windrunner", name = "Sylvanas Windrunner", note = "matou o homem que ele foi" },
	},
})

Translate("ptBR", "the-abandoned", {
	title = "O Abandonado",
	subtitle = "O Frio de Market Street",
