	allegiance = "Flagelo",
	sections = {
		{
			title = "Resumo",
			text = [=[O Abandonado é um conjurador morto-vivo que assombra uma velha praça da capital arruinada. Ele não surge de imediato. Primeiro os mortos se reúnem em ondas ao redor de uma estátua, e só quando eles caem é que ele aparece. Ele se envolve em gelo, prende os inimigos no gelo e drena a vida deles para alimentar a sua. Carrega um cetro que os {link:forsaken}Renegados{/link} cobiçam.]=],
		},
